input.command:
cd "/c/visual projects/alpha" && python -c "
import json
for f in ['dash','money','p05-a1','e26','filt']:
    d=json.load(open(f'data/kpi/{f}-closes.json',encoding='utf-8'))
    for k,v in d.items():
        for mp,periods in v.items():
            for pk,evs in periods.items():
                if evs:
                    print(f,k,mp,pk,len(evs[0]))
                break
            break
        break
"

