function renderApproach() {
  const box = document.getElementById("panel-approach"), A = NH && NH.approach;
  if (!A || !A.by_number) { box.style.display = "none"; return; }
  document.getElementById("approach-note").innerHTML = "Только главный вариант (BTC 4 ч, трейл 1/1), готовые сделки, без нового бэктеста: " +
    A.notes.join("; ") + ". Сделок: август " + A.n_trades.aug + ", сентябрь " + A.n_trades.sep + "; максимум номера подхода — " + A.max_approach_number + ".";
  const pc = x => x == null ? "—" : Math.round(x * 100) + "%";
  const rowN = r => "<tr><td>" + r.key + "</td>" + ["aug", "sep"].map(m => {
    const v = r[m];
    return "<td class='num'>" + v.n + "</td><td class='num " + cls(v.usd) + "'>" + money(v.usd) + "</td><td class='num'>" + moneyFine(v.usd_per_trade) +
      "</td><td class='num'>" + pc(v.win) + "</td><td class='num'>" + pc(v.stop) + "</td>";
  }).join("<td class='sep'></td>") + "</tr>";
  document.getElementById("approach-number").innerHTML =
    "<thead><tr><th>подход</th><th colspan='5'>август</th><th class='sep'></th><th colspan='5'>сентябрь</th></tr>" +
    "<tr><th></th><th class='num'>n</th><th class='num'>$</th><th class='num'>$/сделку</th><th class='num'>в плюс</th><th class='num'>стопов</th><th class='sep'></th>" +
    "<th class='num'>n</th><th class='num'>$</th><th class='num'>$/сделку</th><th class='num'>в плюс</th><th class='num'>стопов</th></tr></thead><tbody>" +
    A.by_number.map(rowN).join("") + "</tbody>";
  const n_note = v => v.n < 10 ? "сделок нет" : (v.n < 30 ? " (описание)" : "");
  const gtCell = v => v.n < 10 ? "—" : pc(v.frac_gt_5d) + n_note(v);
  const pmCell = v => v.n < 10 ? "—" : dayFmt((v.p90_days || 0) * 24) + (v.p90_censored ? "*" : "") + " / " + dayFmt((v.max_days || 0) * 24) + (v.max_censored ? "*" : "");
  const rowR = r => "<tr><td>" + r.rule + "</td>" + ["aug", "sep"].map(m => {
    const v = r[m];
    return "<td class='num'>" + v.n + "</td><td class='num " + cls(v.usd) + "'>" + money(v.usd) + "</td><td class='num " + (v.n >= 10 && v.frac_gt_5d > 0.10 ? "neg" : "") +
      "'>" + gtCell(v) + "</td><td class='num muted'>" + pmCell(v) + "</td>";
  }).join("<td class='sep'></td>") + "</tr>";
  document.getElementById("approach-rules").innerHTML =
    "<thead><tr><th>правило</th><th colspan='4'>август</th><th class='sep'></th><th colspan='4'>сентябрь</th></tr>" +
    "<tr><th></th><th class='num'>n</th><th class='num'>$</th><th class='num'>доля &gt; 5 сут</th><th class='num'>p90/max, дн</th><th class='sep'></th>" +
    "<th class='num'>n</th><th class='num'>$</th><th class='num'>доля &gt; 5 сут</th><th class='num'>p90/max, дн</th></tr></thead><tbody>" +
    A.rules.map(rowR).join("") + "</tbody>" +
    "<tfoot><tr><td colspan='10' class='muted'>Просмотрено правил: " + A.n_rules + " (все выписаны, без подбора, на тех же днях главного варианта — не проверка). Цель — доля &le; 10 %. Г-85 — считается (размеченных сделок по номеру подхода для Г-85 пока нет).</td></tr></tfoot>";
}

// ---------- плечо ×1..×5 (владелец 27.09: «не размер позиции а в плечах») ----------
function renderLev() {
  const box = document.getElementById("panel-lev"), L = NH && NH.lev;
  if (!L || !L.rows) { box.style.display = "none"; return; }
  document.getElementById("lev-note").innerHTML = L.notes.join("; ") + ". " + L.note_scale_invariant +
    (L.frac_gt_h ? " (август " + Math.round(L.frac_gt_h.aug * 100) + "%, сентябрь " + Math.round(L.frac_gt_h.sep * 100) + "%, все ×)." : ".");
  const mults = [1, 2, 3, 4, 5];
  const metric = (label, get, pct) => "<tr><td>" + label + "</td>" + ["aug", "sep"].map(m => mults.map(x => {
    const r = (L.rows[m] || {})[x]; if (!r) return "<td class='num'>—</td>";
    const v = get(r);
    return "<td class='num" + (r.dd_pct_approx && label.includes("просадк") ? " muted" : "") + "'>" + (v == null ? "—" : pct ? v.toFixed(1) + "%" : v) + (r.dd_pct_approx && label.includes("просадк") ? " ≈" : "") + "</td>";
  }).join("")).join("<td class='sep'></td>") + "</tr>";
  let h = "<thead><tr><th>×</th>" + ["август", "сентябрь"].map(mo => "<th colspan='5'>" + mo + "</th>").join("<th class='sep'></th>") + "</tr>" +
    "<tr><th></th>" + ["aug", "sep"].map(() => mults.map(x => "<th class='num'>×" + x + " ($" + L.sizes[x] + ")</th>").join("")).join("<th class='sep'></th>") + "</tr></thead><tbody>";
  h += metric("$", r => r.usd, false).replace("<td>$</td>", "<td>$</td>");
  h += metric("% депозита", r => r.pct, true);
  h += metric("максимальная просадка, % депозита", r => r.dd_pct, true);
  h += metric("худшие сутки, % депозита", r => r.worst_day_pct, true);
  h += metric("стресс обвала (−59,7 % на пике), % депозита", r => r.stress_pct, true);
  h += metric("пиковое фактическое плечо", r => r.lev, false).replace(/(<td class='num[^']*'>)(-?[\d.]+)(<\/td>)/g, (s, a, v, b) => a + "×" + v + b);
  document.getElementById("lev-table").innerHTML = h + "</tbody>";
}

