    "<tfoot><tr><td colspan='10' class='muted'>Просмотрено правил: " + A.n_rules + " (все выписаны, без подбора, на тех же днях главного варианта — не проверка). Цель — доля &le; 10 %. Г-85 — считается (размеченных сделок по номеру подхода для Г-85 пока нет).</td></tr></tfoot>";
}

// ---------- плечо ×1..×5 (владелец 27.09: «не размер позиции а в плечах») ----------
function renderLev() {
  const box = document.getElementById("panel-lev"), L = NH && NH.lev;
  if (!L || !L.rows) { box.style.display = "none"; return; }
  document.getElementById("lev-note").innerHTML = L.notes.join("; ") + ". " + L.note_scale_invariant +
    (L.frac_gt_h ? " (август " + Math.round(L.frac_gt_h.aug * 100) + "%, сентябрь " + Math.round(L.frac_gt_h.sep * 100) + "%, все ×)." : ".");
  const mults = [1, 2, 3, 4, 5];
  const metric = (label, get, pct) => "<tr><td>" + label + "</td>" + ["aug", "sep"].map(m => mults.map(x => {
    const r = (L.rows[m] || {})[x]; if (!r) return "<td class='num'>—</td>";
    const v = get(r);
    return "<td class='num" + (r.dd_pct_approx && label.includes("просадк") ? " muted" : "") + "'>" + (v == null ? "—" : pct ? v.toFixed(1) + "%" : v) + (r.dd_pct_approx && label.includes("просадк") ? " ≈" : "") + "</td>";
  }).join("")).join("<td class='sep'></td>") + "</tr>";
  let h = "<thead><tr><th>×</th>" + ["август", "сентябрь"].map(mo => "<th colspan='5'>" + mo + "</th>").join("<th class='sep'></th>") + "</tr>" +
    "<tr><th></th>" + ["aug", "sep"].map(() => mults.map(x => "<th class='num'>×" + x + " ($" + L.sizes[x] + ")</th>").join("")).join("<th class='sep'></th>") + "</tr></thead><tbody>";
  h += metric("$", r => r.usd, false).replace("<td>$</td>", "<td>$</td>");
  h += metric("% депозита", r => r.pct, true);
  h += metric("максимальная просадка, % депозита", r => r.dd_pct, true);
  h += metric("худшие сутки, % депозита", r => r.worst_day_pct, true);
  h += metric("стресс обвала (−59,7 % на пике), % депозита", r => r.stress_pct, true);
  h += metric("пиковое фактическое плечо", r => r.lev, false).replace(/(<td class='num[^']*'>)(-?[\d.]+)(<\/td>)/g, (s, a, v, b) => a + "×" + v + b);
  document.getElementById("lev-table").innerHTML = h + "</tbody>";
}

